code_sketch:
await foreach (var m in consumer.ReceiveMessagesAsync(ct))
{
    if (!IsInteresting(m))            // header/property check, no body parse
    {
        await consumer.CompleteMessageAsync(m, ct);   // settle: a drop must not lock the queue
        Interlocked.Increment(ref dropped);
        continue;
    }
    await HandleAsync(m, ct);
}

static bool IsInteresting(Message m) => m.ApplicationProperties["type"] is "price";

